// One completion standard for manual entry, sample import, and voice assistance.
const categoryIntake={
 Photographer:{shooting:'Describe how you direct portraits versus candid coverage.',editing:'Describe your editing and retouching boundaries.',imageRights:'Explain personal-use rights and restrictions on editing images.',rawPolicy:'What is your RAW-file and image-retention policy?',galleryAccess:'How long is the online gallery available?',albumProcess:'Describe album design, revisions, and delivery.',shotList:'When and how do couples submit family photo and must-have lists?',secondShooter:'How do you staff a second photographer or replace an unavailable lead?'},
 DJ:{musicPlanning:'Describe playlist planning and do-not-play requests.',requests:'How do you handle guest song requests?',cleanMusic:'Describe explicit-content and clean-edit preferences.',ceremonyAudio:'Explain ceremony microphones, sound zones, and operator coverage.',powerPlan:'List power, shelter, and performance-space requirements.',soundLimits:'How do you handle venue sound limits and curfews?',mcScope:'Explain announcements and MC responsibilities.',equipmentFailure:'What happens if audio equipment fails during the event?'},
 Venue:{accessibility:'Describe step-free routes, restrooms, and accessibility limitations.',parking:'Describe parking capacity, shuttles, and transport constraints.',rainCapacity:'Give the indoor rain-plan capacity and changeover deadline.',alcoholRules:'Explain bar service, alcohol permits, and approved providers.',soundCurfew:'List amplified-sound rules and event end times.',vendorRules:'Explain required, preferred, and external vendor policies.',cleanup:'List cleanup responsibilities, waste removal, and collection deadlines.',accommodation:'Describe overnight accommodation and getting-ready access.'},
 Caterer:{allergens:'Explain allergen disclosure and cross-contact limitations.',dietaryMenus:'Describe vegetarian, vegan, gluten-free, and other dietary options.',kitchenNeeds:'List kitchen, potable water, power, and prep-space requirements.',serviceware:'Explain what plates, flatware, linens, and serving equipment are included.',tastingPolicy:'Describe tasting availability, charges, and guest limits.',headcount:'When is the guaranteed headcount due and how are changes billed?',leftovers:'Explain leftover food handling and food-safety restrictions.',staffing:'List service staffing, breaks, cleanup, and overtime responsibilities.'}
};
Object.assign(vendorGroups[5].fields,{insurer:'Insurer / provider',liability:'Liability limit and covered services',expiry:'Certificate expiry / renewal date',documentPlan:'Document availability or follow-up plan'});
const depthStages=['Get started','Business & contacts','Services & fit','Packages & pricing','Logistics & policies','Portfolio & listing','Documents & checks','Preview & publish'];stages.splice(0,stages.length,...depthStages);
const folders={Photographer:'photographer',DJ:'dj',Venue:'venue',Caterer:'caterer'};
const privateVendorKeys=new Set(['contact','address','insurance','license','reference','followup','insurer','liability','expiry','documentPlan']);
const stageHints={1:'Gather your business contact details, studio address, and service territory.',2:'Define what you do, what you exclude, and the constraints a couple needs to know.',3:'Gather your current rate card. Enter three package tiers, inclusions, overtime, travel, and fees. If a tier is not offered, explicitly record “Not offered” for its fields.',4:'Have your contract and event-day checklist handy. Capture payment terms, change policies, and contingency plans.',5:'Gather portfolio links, an event example, display permissions, and search terms.',6:'Gather your certificate, license details, and reference information. Missing paperwork needs an honest status and a follow-up plan; coverage is never verified by this demo.'};
const stageGather={1:'Business records · booking contacts · territory list',2:'Service guide · category operating procedures',3:'Current rate card · inclusions · fee schedule',4:'Contract · payment schedule · event-day checklist',5:'Portfolio collections · image permissions · credits',6:'Insurance certificate · permits · reference details'};
let packet=null,docTab='website';v.sectionReviews=v.sectionReviews||{};v.confirmedDelivery=!!v.confirmedDelivery;
if(!v.depthVersion){v.step=({0:0,1:1,2:2,3:6,4:7})[v.step]??0;v.depthVersion=11;v.reviewed=false;save()}
function intakeFields(stage){const group=vendorGroups[stage-1];return {...(group?.fields||{}),...(stage===2?categoryIntake[v.type]:{})}}
function intakeKeys(){return [1,2,3,4,5,6].flatMap(s=>Object.keys(intakeFields(s)))}
function publicVendorData(data){return Object.fromEntries(Object.entries(data).filter(([key])=>!privateVendorKeys.has(key)))}
required=function(){return intakeKeys().filter(k=>!String(v.data[k]||'').trim())};
function stageMissing(stage){return Object.keys(intakeFields(stage)).filter(k=>!String(v.data[k]||'').trim())}
function missingSummary(stage){return stageMissing(stage).map(k=>intakeFields(stage)[k]).join(', ')}
function depthStatus(){const keys=intakeKeys(),filled=keys.length-required().length,sourced=keys.filter(k=>v.evidence[k]).length;return `<div class="intake-meter"><div><b>${filled} / ${keys.length}</b><span> details recorded</span></div><div class="progress"><span style="width:${filled/keys.length*100}%"></span></div><p class="small">${v.method==='manual'?'Manual entry: gather and record each answer.':`${sourced} source-backed draft fields · ${required().length} still need answers.`} ${Object.values(v.sectionReviews).filter(Boolean).length} / 6 sections confirmed.</p></div>`}
const originalStart=startScreen,originalField=field,originalListing=listing,originalPreview=preview;
startScreen=function(){return originalStart().replace('A few essentials first. You can add a portfolio and supporting documents later.','Complete the same 58-field intake as the assisted path. Gather your rate card, contract, service guide, portfolio permissions, and insurance records. Every answer starts blank.').replace('Create a listing that feels like your business. Start with what you have; we’ll help you bring the details together.','A complete listing takes more than a name and a price. Build your service details, package tiers, booking policies, portfolio, and document record.').replace('How would you like to begin?','How would you like to complete the intake?').replace('data-action="next">Let’s get started →','data-depth="manual-start">Begin blank manual intake →').replace('<div class="choices">',`<div class="intake-brief"><b>58 fields · 6 sections · 5 source documents</b><p>Manual entry means gathering the answers across your business records. Assistance organizes supported details into the same intake; you confirm the facts and supply the gaps.</p><span class="small">No estimated time savings are claimed. The workload is visible below.</span></div><div class="choices">`).replace('Review a draft from your existing business details.','Prefill supported answers from the sample business packet.').replace('Your website or portfolio','Your website or portfolio').replace('Try Golden Hour Photography →','Try Golden Hour Photography →')}
field=function(k,label,options={}){let markup=originalField(k,label,{...options,optional:false});const proof=v.evidence[k];if(proof?.doc){markup=markup.replace(/<a href="samples\/vendor-[^"]+" target="_blank">Open sample source packet ↗<\/a>/,'');markup=markup.replace('</details>',` <button type="button" class="text" data-source="${proof.doc}">Read ${safe(proof.label)} ↗</button></details>`)}if(privateVendorKeys.has(k))markup=markup.replace('</label>',' <span class="badge">Private intake</span></label>');return markup}
function packetTools(){return `<section class="panel packet-tools"><span class="eyebrow">SOURCE MATERIALS</span><h3>Your business records</h3><p class="small">${v.sample?'Read the actual fictional source documents used for the sample draft.':'Use your own records, or inspect the fictional packet as a manual-entry exercise.'}</p><div class="doc-tabs">${[['website','Website'],['call','Call transcript'],['rates','Rate card'],['email','Follow-up email'],['portfolio','Portfolio brief']].map(([key,label])=>`<button class="text" data-source="${key}">${label} ↗</button>`).join('')}</div><p class="small">The same packet is available in both paths. Opening a source does not fill manual fields.</p></section>`}
function categoryLabel(k,label){return label}
function detailSection(stage){const group=vendorGroups[stage-1],fields=intakeFields(stage),count=Object.keys(fields).length;return header(group.title+'.<br><em>All the particulars.</em>',stageHints[stage])+depthStatus()+`<div class="depth-layout"><section class="panel"><div class="section-heading"><div><span class="eyebrow">SECTION ${stage} OF 6</span><h2>${safe(group.title)}</h2></div><span class="badge">${count-stageMissing(stage).length} / ${count} answered</span></div><div class="gather"><b>Have ready:</b> ${stageGather[stage]}</div>${stage===2?`<div class="banner">Includes eight additional questions specific to ${v.type==='DJ'?'DJs':v.type.toLowerCase()+'s'}. These cannot be answered by a generic business description.</div>`:''}${stage===3&&v.sample&&!v.confirmedPrice?`<div class="banner warn"><b>Conflicting starting prices</b><p>Your older website says ${safe(packet?.oldPrice||v.oldPrice)}. The current rate card and follow-up email say ${safe(packet?.fields.price.value||categories[v.type].price)}. Review the documents before choosing.</p><button class="text" data-source="rates">Open rate card ↗</button> <button class="text" data-source="email">Read follow-up ↗</button><p><button class="secondary" data-depth="resolve-price">Use current documented price</button></p></div>`:''}${stage===4&&v.sample&&!v.confirmedDelivery?`<div class="banner warn"><b>Confirm the current delivery / planning timeline</b><p>The original website or call is outdated or incomplete. Your follow-up email gives the current deadline.</p><button class="text" data-source="email">Compare the follow-up ↗</button> <button class="secondary" data-depth="resolve-delivery">Use confirmed timeline</button></div>`:''}<div class="fields">${Object.entries(fields).map(([k,label])=>field(k,categoryLabel(k,label),{full:!['name','contact','email','phone','years','website','package1','price','package2','price2','package3','price3','insurer','expiry'].includes(k),type:k==='email'?'email':k==='website'?'url':['name','contact','phone','years','package1','price','package2','price2','package3','price3','insurer','expiry'].includes(k)?'text':'textarea',hint:hintFor(k)})).join('')}</div>${stage===3?`<div class="checkrow"><input id="price-confirm" type="checkbox" ${v.confirmedPrice?'checked':''}><label for="price-confirm">I confirm the current package prices, inclusions, and additional charges.</label></div>`:''}${stage===4?`<div class="checkrow"><input id="delivery-confirm" type="checkbox" ${v.confirmedDelivery?'checked':''}><label for="delivery-confirm">I confirm the current delivery timeline and booking policies.</label></div>`:''}${stage===5?photoControl():''}${stage===6?documentControl():''}<div class="checkrow"><input id="section-confirm" type="checkbox" ${v.sectionReviews[stage]?'checked':''}><label for="section-confirm">I’ve checked every answer in ${safe(group.title.toLowerCase())} against my business records. Where something is unavailable or not applicable, I’ve explained that explicitly.</label></div>${stage===6?`<div class="checkrow"><input id="publish-consent" type="checkbox" ${v.consent?'checked':''}><label for="publish-consent">I’m authorized to represent this business and publish the public details and images I provide.</label></div>`:''}${actions(stage===6?'Preview my completed listing →':'Save section & continue →')}</section><aside class="depth-aside">${mini()}${packetTools()}<section class="panel"><span class="eyebrow">TO COMPLETE THIS SECTION</span><ul class="checklist">${stageMissing(stage).slice(0,8).map(k=>`<li>○ ${safe(fields[k])}</li>`).join('')||'<li>✓ All fields have an answer. Review and confirm the section.</li>'}${stageMissing(stage).length>8?`<li>+ ${stageMissing(stage).length-8} more answers</li>`:''}</ul></section></aside></div>`}
function hintFor(k){return ({address:'Private business record; not shown on your listing.',contact:'Private operational contact; couples use the public booking email.',gallery:'Include collection URLs and a brief description of the work.',credit:'State the permissions and credits needed to display your portfolio.',license:'List applicable permits and their status. If not applicable, explain why.',reference:'Private reference details or a plan to obtain permission to contact them.',followup:'List any outstanding items, who will obtain them, and when. If none, state that.',insurance:'State uploaded, pending, expired, or not carried, with an explanation. This is not coverage verification.',insurer:'If unavailable, state that and explain the follow-up plan below.',expiry:'Use a date, or explicitly state that the certificate has not been supplied.',documentPlan:'Describe which records you still need, who is responsible, and the next action.',price:'Include currency and the pricing unit. If this tier is not offered, explicitly state “Not offered”.',price2:'Include the price and unit, or “Not offered”.',price3:'Include the price and unit, or “Not offered”.',tax:'Specify service fees, taxes, gratuity, and any mandatory charges.'})[k]||'Be specific. If not applicable, explain why rather than leaving the answer blank.'}
function photoControl(){return `<hr class="divider"><h3>Portfolio cover</h3><div class="upload"><label for="cover-upload">Cover photograph (optional)</label><input id="cover-upload" type="file" accept="image/jpeg,image/png,image/webp"><p class="helper">JPG, PNG or WebP · up to 2 MB. Your portfolio permissions above must cover its use.</p>${v.photo?`<div class="art photo-preview"><img src="${safe(v.photo)}" alt="Your portfolio cover"></div><button class="text" data-action="remove-photo">Remove photograph</button>`:''}</div>`}
function documentControl(){return `<hr class="divider"><h3>Private supporting document</h3><div class="upload"><label for="insurance-upload">Attach insurance certificate</label><input id="insurance-upload" type="file" accept="application/pdf,image/jpeg,image/png"><p class="helper">PDF, JPG or PNG · up to 5 MB. File bytes remain in this page session. You can publish with pending paperwork if the status and follow-up plan are recorded honestly.</p>${v.insuranceName?`<p class="filename">${insuranceFile?'Attached this session':'Previously selected; reattach to view'}: ${safe(v.insuranceName)}</p>${insuranceFile?'<button class="text" data-action="view-insurance">View attachment ↗</button>':''}`:''}<a class="small" href="samples/golden-hour-sample-certificate.pdf" download>Download fictional sample certificate ↓</a></div>`}
errorsFor=function(stage){const missing=stageMissing(stage);if(missing.length)return `${vendorGroups[stage-1]?.title}: ${missing.length} answers still needed — ${missing.slice(0,3).map(k=>intakeFields(stage)[k]).join(', ')}${missing.length>3?'…':''}.`;if(stage===1){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.data.email))return 'Enter a valid public booking email.';if(!validUrl(v.data.website)&&!/^not applicable\b/i.test(v.data.website))return 'Enter a valid http:// or https:// business website.'}if(stage===3&&!v.confirmedPrice)return 'Confirm your current package prices, inclusions, and charges.';if(stage===4&&!v.confirmedDelivery)return 'Confirm the current timeline and booking policies.';if(!v.sectionReviews[stage])return `Review and confirm ${vendorGroups[stage-1].title.toLowerCase()} before continuing.`;if(stage===6&&!v.consent)return 'Confirm you’re authorized to publish the business details.';return ''}
shell=function(content){return vendorTop()+`<div class="layout"><aside class="rail"><span class="eyebrow">COMPLETE YOUR BUSINESS PROFILE</span>${stages.map((label,i)=>`<button class="step ${v.step===i?'active':i>0&&i<7&&v.sectionReviews[i]?'done':''}" data-stage="${i}" ${busy?'disabled':''}><i>${i>0&&i<7&&v.sectionReviews[i]?'✓':i+1}</i>${label}</button>`).join('')}<div class="rail-foot">${depthStatus()}<button class="text" data-action="voice">Help me with these details ↗</button>${v.published?'<p><button class="text" data-action="view">View published listing</button></p>':''}<p class="quiet"><a href="team-demo.html">Presentation & evals ↗</a></p></div></aside><main class="workspace">${content}${error?`<div role="alert" class="error depth-error">${safe(error)}</div>`:''}</main></div>`}
function overviewRequirements(){return `<div class="panel requirements-overview"><span class="eyebrow">THE SAME REQUIREMENTS IN EVERY PATH</span><h2>What a complete profile really takes.</h2><div class="requirements-grid">${[1,2,3,4,5,6].map(s=>`<button data-stage="${s}"><b>${safe(vendorGroups[s-1].title)}</b><span>${Object.keys(intakeFields(s)).length} fields</span><small>${stageGather[s]}</small></button>`).join('')}</div><p class="small">Manually enter every answer, or use supported source material to draft the same fields. No path skips the requirements.</p></div>`}
const depthBasePreview=preview;preview=function(){return depthStatus()+`<div class="completion-audit"><h3>Before this goes live</h3>${[1,2,3,4,5,6].map(s=>`<button class="audit-row" data-stage="${s}"><span>${safe(vendorGroups[s-1].title)}</span><span>${stageMissing(s).length?`${stageMissing(s).length} missing`:!v.sectionReviews[s]?'Review needed':'✓ Confirmed'} →</span></button>`).join('')}</div>`+depthBasePreview().replace(/\d+ essentials missing:[\s\S]*?(?=<button class="text" data-stage="1">Finish my details)/,`${required().length} required answers are still missing. Use the section checklist above to finish them. `).replace('data-stage="1">Finish my details','data-stage="1">Finish my details').replace('Confirm that you’ve reviewed','Confirm that you’ve reviewed')}
listing=function(data,photo,published=false,type=v.type,isSample=v.sample){let html=originalListing(data,photo,published,type,isSample);const extra=`<section class="listing-more"><hr class="divider"><h2>Packages & what’s included</h2><div class="package-grid">${[1,2,3].map(n=>data['package'+n]?`<article><span class="eyebrow">${safe(data['package'+n])}</span><h3>${safe(data[n===1?'price':'price'+n])}</h3><p>${safe(data['includes'+n])}</p></article>`:'').join('')}</div><hr class="divider"><h2>Planning your celebration</h2><div class="public-facts">${['style','capacity','coverage','team','custom','exclusions','requirements','travel','tax','deposit','balance','lead','setup','delivery','cancellation','reschedule','backup','years','headline','gallery','featured','credit','tags'].filter(k=>data[k]).map(k=>`<div><b>${safe(vendorGroups.flatMap(g=>Object.entries(g.fields)).find(([key])=>key===k)?.[1]||k)}</b><p>${safe(data[k])}</p></div>`).join('')}</div></section>`;return html+extra+`<section class="listing-more"><hr class="divider"><h2>More about working with us</h2><div class="public-facts">${Object.entries(categoryIntake[type]).filter(([key])=>data[key]).map(([key,label])=>`<div><b>${safe(label)}</b><p>${safe(data[key])}</p></div>`).join('')}</div></section>`}
async function loadPacket(){const response=await fetch(`samples/${folders[v.type]}/packet.json`);if(!response.ok)throw Error('Could not open the sample documents.');packet=await response.json();return packet}
async function showPacket(tab){try{if(!packet||packet.type!==v.type)await loadPacket();docTab=tab;let dialog=q('#intake-source');if(!dialog){dialog=document.createElement('dialog');dialog.id='intake-source';document.body.append(dialog)}const doc=packet.documents[tab];dialog.innerHTML=`<button class="secondary" id="close-intake-source">Close document ×</button><h2>${safe(doc.title)}</h2><p class="small">Fictional sample · The same evidence is available in manual and assisted entry.</p><pre>${safe(doc.text)}</pre><a class="secondary" href="samples/${folders[v.type]}/${safe(doc.filename)}" download>Download source ↓</a>`;dialog.querySelector('#close-intake-source').onclick=()=>dialog.close();dialog.showModal()}catch(e){notify(e.message)}}
importSample=async function(){if(!v.sample||v.sourceUrl!==categories[v.type].website){error='Live import is not enabled. Select the sample packet, or complete the same intake manually.';render();return}if(Object.values(v.data).some(Boolean)&&!confirm('Replace the current draft answers with a new source-backed sample draft? Your previously published listing will remain intact.'))return;busy=true;render();try{await loadPacket();q('.workspace').innerHTML=header('Gathering the whole story.','Organizing five fictional documents into the full onboarding requirements.')+`<section class="panel loading" role="status"><div class="spinner"></div><h2>More than a business card.</h2><p id="depth-progress">Reading the website and interview transcript…</p><p class="small">Simulated extraction · No live website is fetched</p></section>`;for(const message of ['Structuring three packages, fees, and booking policies…','Cross-checking prices and delivery deadlines…','Separating supported answers from missing details…']){await new Promise(r=>setTimeout(r,1600));q('#depth-progress').textContent=message}v.data={};v.evidence={};for(const [key,proof]of Object.entries(packet.fields)){if(['insurance','license','reference','followup'].includes(key))continue;v.data[key]=proof.value;const doc=packet.documents[proof.doc];v.evidence[key]={value:proof.value,quote:doc.text.slice(proof.start,proof.end),label:doc.title,doc:proof.doc}}v.oldPrice=packet.oldPrice;v.data.price=packet.oldPrice;const website=packet.documents.website.text;const start=website.indexOf(packet.oldPrice);v.evidence.price={value:packet.oldPrice,quote:website.slice(Math.max(0,start-20),start+packet.oldPrice.length+1),label:packet.documents.website.title,doc:'website'};v.data.delivery=v.type==='Photographer'?'Full galleries in 6 weeks':'Timeline not yet confirmed';v.evidence.delivery={value:v.data.delivery,quote:packet.documents.website.text,label:packet.documents.website.title,doc:'website'};v.sectionReviews={};v.confirmedPrice=false;v.confirmedDelivery=false;v.reviewed=false;v.consent=false;busy=false;navigate(1);notify(`${Object.keys(v.evidence).length} fields drafted from the packet. Review conflicts and supply ${required().length} missing answers.`)}catch(e){busy=false;error=e.message;render()}}
const depthOriginalBind=bindVendor;bindVendor=function(){depthOriginalBind();document.querySelectorAll('[data-field]').forEach(el=>{const old=el.oninput;el.oninput=()=>{old();v.sectionReviews[v.step]=false;if(el.dataset.field==='delivery'){v.confirmedDelivery=false;if(q('#delivery-confirm'))q('#delivery-confirm').checked=false}if(['price','price2','price3','includes1','includes2','includes3','overtime','travel','tax'].includes(el.dataset.field)){v.confirmedPrice=false;if(q('#price-confirm'))q('#price-confirm').checked=false}if(q('#section-confirm'))q('#section-confirm').checked=false;save();document.querySelectorAll('.intake-meter').forEach(meter=>meter.outerHTML=depthStatus());const badge=q('.section-heading .badge');if(badge){const total=Object.keys(intakeFields(v.step)).length;badge.textContent=(total-stageMissing(v.step).length)+' / '+total+' answered'}}});document.querySelectorAll('[data-source]').forEach(el=>el.onclick=()=>showPacket(el.dataset.source));if(q('#section-confirm'))q('#section-confirm').onchange=e=>{v.sectionReviews[v.step]=e.target.checked;v.reviewed=false;save()};if(q('#delivery-confirm'))q('#delivery-confirm').onchange=e=>{v.confirmedDelivery=e.target.checked;v.sectionReviews[4]=false;v.reviewed=false;save();if(q('#section-confirm'))q('#section-confirm').checked=false};document.querySelectorAll('[data-depth]').forEach(el=>el.onclick=async()=>{if(el.dataset.depth==='manual-start'){v.data={};v.evidence={};v.sample=false;v.sectionReviews={};v.confirmedPrice=false;v.confirmedDelivery=false;v.reviewed=false;v.consent=false;v.photo='';v.insuranceName='';insuranceFile=null;navigate(1);return}try{if(!packet||packet.type!==v.type)await loadPacket();const key=el.dataset.depth==='resolve-price'?'price':'delivery',p=packet.fields[key],doc=packet.documents[p.doc];v.data[key]=p.value;v.evidence[key]={value:p.value,quote:doc.text.slice(p.start,p.end),label:doc.title,doc:p.doc};v.sectionReviews[v.step]=false;v.reviewed=false;if(key==='price')v.confirmedPrice=true;else v.confirmedDelivery=true;save();render()}catch(e){notify(e.message)}});const priceBox=q('#price-confirm');if(priceBox){const old=priceBox.onchange;priceBox.onchange=e=>{old(e);v.sectionReviews[3]=false;save();if(q('#section-confirm'))q('#section-confirm').checked=false}}}
const savedRender=render;render=function(){if(page==='listing'||page==='saved'){savedRender();return}q('#vendor-app').innerHTML=shell(v.step===0?startScreen()+overviewRequirements():v.step===7?preview():detailSection(v.step));bindVendor()};
render();
